    // Should reject because other field is not in schema but is present
    expect(response.result).not.toContain('secret@example.com');
  });

  it('rejects enum constraint violation and names the field', async () => {
    const registry = new ToolRegistry();
    let executorCallCount = 0;
    registry.register(
      {
        name: 'enum_tool',
        description: 'Tool with enum',
        inputSchema: {
          type: 'object',
          properties: {
            status: {type: 'string', enum: ['active', 'inactive']},
          },
          required: ['status'],
        },
      },
      async () => {
        executorCallCount += 1;
        return 'result';
      }
    );

    const response = await registry.execute('enum_tool', {status: 'invalid'}, undefined);

    expect(executorCallCount).toBe(0);
